"""MG158 report and normalized accuracy figure from verified raw decisions."""
import os
for k in ('OPENBLAS_NUM_THREADS','OMP_NUM_THREADS','MKL_NUM_THREADS'):os.environ[k]='1'
import json,time,math
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from mg12h3_tick_accuracy import BASE,read,hashes
from mg10e2c1_pool import atomic_json
def report():
    start=time.perf_counter();primary=read(BASE/'accuracy_results.json');second=read(BASE/'separate_accuracy_recomputation.json');assert second['passed'];assert primary['source_hashes']==hashes();assert read(BASE/'analysis_attempt.json')['status']=='COMPLETE';margins=np.asarray(primary['margins']);np.testing.assert_array_equal(margins,second['margins']);agreement=[]
    for a,b in zip(primary['comparisons'],second['comparisons']):
        for field in ('mean','lower','upper'):np.testing.assert_allclose(a[field],b[field],rtol=1e-10,atol=1e-12)
        assert a['labels']==b['labels'] and a['overall']==b['overall'];agreement.append(dict(comparison=a['comparison'],passed=True))
    atomic_json(BASE/'interval_agreement.json',dict(passed=True,comparisons=agreement))
    names=['G contrast','X contrast','Y contrast','G change power','X change power','Y change power'];labels=[f'{name}, t={t:g}' for t in (.005,.01) for name in names];fig,axes=plt.subplots(1,2,figsize=(12,7),sharey=True)
    edges=[];table=[];details=[];diagnostics=[]
    for c,(a,b) in enumerate(zip(primary['comparisons'],second['comparisons'])):
        low=np.asarray(a['lower']);high=np.asarray(a['upper']);mean=np.asarray(a['mean']);edge=np.maximum(abs(low),abs(high))/margins;edges.append(float(edge.max()));n=a['N'];tick=(.0001,.00005)[c];y=np.arange(12);normalized=(mean/margins).ravel();axis=axes[c];axis.axvspan(-1,1,color='#e6f3e8');axis.axvline(0,color='#777777',lw=.7);axis.axvline(-1,color='#33804a',ls='--');axis.axvline(1,color='#33804a',ls='--');axis.errorbar(normalized,y,xerr=np.array([((mean-low)/margins).ravel(),((high-mean)/margins).ravel()]),fmt='o',capsize=3,color=('#245a9c','#9d4f17')[c]);axis.set_title(f'Tick {tick:g} vs 0.00002; N={n} pairs');axis.set_xlim(-1.12,1.12);axis.set_xlabel('Mean difference and interval / allowed margin');axis.grid(axis='y',alpha=.18);table.append(f"| {tick:g} | {n} | {a['overall'].upper()} | {edge.max():.6g} |")
        for frame,t in enumerate((.005,.01)):
            for s,name in enumerate(names):details.append(f"| {tick:g} | {t:g} | {name} | {mean[frame,s]:.6g} | [{low[frame,s]:.6g}, {high[frame,s]:.6g}] | {margins[s]:.6g} | {a['labels'][frame][s]} |")
        sk=np.asarray(a['skewness']);kurt=np.asarray(b['population_moment_excess_kurtosis']);share=np.asarray(b['max_variance_share']);diagnostics.append(dict(comparison=c,max_abs_skew=float(abs(sk).max()),max_excess_kurtosis=float(kurt.max()),max_single_replicate_variance_share=float(share.max())))
    axes[0].set_yticks(np.arange(12),labels);axes[0].invert_yaxis();fig.suptitle('MG158: all registered accuracy intervals lie within the tolerance band',fontsize=14);fig.text(.5,.015,'Green band = allowed range. Contrast margins: 5% of initial projected contrast; change-power margin: 0.05.',ha='center',fontsize=9);fig.tight_layout(rect=(0,.04,1,.95));fig.savefig(BASE/'MG158_accuracy_intervals.png',dpi=160);fig.savefig(BASE/'MG158_accuracy_intervals.svg');plt.close(fig)
    sessions=[read(BASE/f'session_{s}_attempt.json') for s in (1,2,3)];ledgers=[read(BASE/f'session_{s}/ledger.json') for s in (1,2,3)];records=[r for l in ledgers for r in l['records']];assert len(records)==320 and all(r['status']=='COMPLETE' and r['returncode']==0 for r in records);charged=sum(s['charged_worker_seconds'] for s in sessions);wall=sum(s['wall_seconds'] for s in sessions);active=read(BASE/'analysis_attempt.json')['elapsed_seconds']+read(BASE/'separate_analysis_attempt.json')['elapsed_seconds'];events=sum(r['events'] for r in records)
    atomic_json(BASE/'budget_summary.json',dict(worker_seconds=charged,worker_core_hours=charged/3600,worker_ceiling=300000,wall_seconds=wall,sessions=sessions,active_audit_recompute_seconds=active,active_parent_ceiling=1800,report_generation_seconds_so_far=time.perf_counter()-start,completed_pairs=320,marginal_chains=640,failures=0,retries=0,event_count=events));atomic_json(BASE/'tail_diagnostics.json',dict(diagnostics=diagnostics,meaning='Descriptive only; no sample exclusion or scoring-method change. Kurtosis uses population moments; skewness is bias-corrected.'))
    all_equivalent=all(c['overall']=='equivalent' for c in primary['comparisons']);assert all_equivalent
    summary="Both tested tick sizes met the accuracy criterion we set in advance: at the two registered observation times, every measured G/X/Y pattern-contrast and short-scale change-power difference agreed closely enough with the finest reference tick. This means the paired method has now done more than reduce noise: it has supported a direct accuracy decision for the strict-tick hypergraph engine in this tested case. We can use these resolutions with greater confidence for this short-horizon numerical task and consider moving toward longer pattern-persistence studies. The result concerns ensemble means of the specified measurements on one prepared state; it does not establish full-field agreement, long-term particle survival, exact continuum accuracy, physical seconds, or a quantum-vacuum origin for A/B."
    lines=['# MG158 — paired tick accuracy qualification results','',summary,'','## Registered result','',
    '**EQUIVALENT for both candidate ticks within the registered scope.** All 24 primary intervals lie entirely inside their respective tolerance bands. PI closure remains pending. No margins, denominators, estimators or scoring rules were changed after seeing the data.',
    '','| Tick compared with 0.00002 | Fresh pairs | Registered classification | Largest interval edge / margin |','|---|---:|---|---:|',*table,'',
    f'The closest interval to a tolerance boundary used {edges[0]*100:.6g}% of the allowed margin for tick 0.0001 and {edges[1]*100:.6g}% for tick 0.00005. Both were Y-contrast intervals. Some mean differences are detectably nonzero; equivalence here means small enough for the chosen tolerance, not identical evolution.',
    '','![All registered accuracy intervals normalized by their margins](MG158_accuracy_intervals.png)','',
    '## What was tested','',
    'The frozen canonical finite LOCAL/LOCAL Omega=10, 500-site prepared state was evolved through model time 0.01. There were 256 fresh coupled pairs comparing ticks 0.0001/0.00002 and 64 comparing 0.00005/0.00002, for 320 pairs and 640 marginal chains. Each chain retained its own strict-tick token reservations and reset calendar. Pilot samples were excluded. Only fixed direct projected contrasts were used; no fitted blend or compensator was introduced.',
    '',
    'Primary measurements were G/X/Y projected pattern contrast and G/X/Y high-band change power at model times 0.005 and 0.01. Contrast margins were 5% of the fixed initial projected contrasts; power margins remained the separately defined absolute 0.05. Power includes deterministic and stochastic high-band changes and is not a particle detector. Full mean observation fields are retained in `mean_observation_fields.npz` to support inspection of information a single projection can miss.',
    '',
    'Registration and explicit PI budget approval were published before sampling at `5a41341`; the later runtime handoff is `4015154`. The historically named draft specification is the approved frozen design referenced by approval.json and plan.json. The qualification uses paired Student-t intervals with a Bonferroni adjustment across all 24 primary comparisons, providing nominal simultaneous 95% coverage under the interval assumptions. The finest tick is an operational reference, not exact continuum truth.',
    '','## All primary intervals','',
    '| Candidate tick | Model time | Observable | Mean difference | Adjusted interval | Margin (+/-) | Classification |','|---|---:|---|---:|---|---:|---|',*details,'',
    '## Uncertainty and distribution diagnostics','',
    'Student-t coverage is approximate for non-Gaussian replicate differences. The finer comparison has 64 pairs and some heavy-tailed power differences. The descriptive diagnostics below are retained without dropping any replicate, changing the interval construction or rescoring the registered outcome. They limit any claim that simultaneous coverage is exactly 95%; the report preserves the nominal registered classification rather than asserting a distribution-free theorem.',
    '','| Candidate tick | Maximum absolute skew | Maximum excess kurtosis | Largest single-replicate variance share |','|---|---:|---:|---:|',
    *[f"| {(0.0001,0.00005)[d['comparison']]:g} | {d['max_abs_skew']:.6g} | {d['max_excess_kurtosis']:.6g} | {d['max_single_replicate_variance_share']:.6g} |" for d in diagnostics],
    '',
    'The single-replicate variance share measures the largest squared centered deviation divided by their sum for any primary observable. A large share flags tail sensitivity; it does not authorize removing that observation. Robust-coverage confirmation would be a separate prospective analysis/study, not a post-result replacement of this score.',
    '','## Verification and retention','',
    f"Every saved checkpoint passed integer count reconstruction and conservation checks: {primary['checkpoint_chain_endpoints']} chain checkpoint endpoints. Both full numeric sentinels replayed successfully, including {primary['sentinel_events']/1e6:.6g} million joint events and every retained reservation/reset boundary. Source hashes, seeds, RNG continuity and observation counts passed checks. Separate analysis recomputed projections from raw fields, change power by Fourier Parseval normalization, variances by centered sums of squares, and critical values through the inverse survival function. All 24 interval endpoints and classifications agreed. No simulation was rerun.",
    '',
    'This is separate recomputation by the same author, sharing frozen rule/weight definitions and SciPy distributions, not external replication. All checkpoints, fields, histograms, RNG states, seeds, logs, budgets, source bindings and two complete numeric sentinels are retained in the compact archive. The raw manifest and Git-content verification record document publication. Historical archives remain unchanged.',
    '','## Compute and execution','',
    f"All three fixed sessions completed without failed, replaced or retried jobs. Total session wall time was {wall/3600:.6g} hours; charged worker time was {charged:.6g} seconds ({charged/3600:.6g} core-hours), below the 300,000-second ceiling. Each session was below its 100,000-second worker ceiling. At most eight local workers ran, with one numerical-library thread per worker. Completed audit and separate recomputation used {active:.6g} measured seconds; the active parent/control/audit allowance is 1,800 seconds. Controller waiting is included in wall time, not treated as another continuously occupied core. The production event count was {events/1e9:.6g} billion joint events (shared events counted once).",
    '','## Recommended next step','',
    'Close this bounded accuracy qualification, then prepare a longer pattern-persistence study with explicit survival, shape and drift measurements and a separately measured compute budget. Tick 0.0001 is the cheaper of the two qualified candidates and is reasonable for a pilot within the tested numerical setting; its agreement over much longer evolution must be checked prospectively rather than assumed. Retain the finer reference/control trajectories. No new simulation batch has been launched by this report.',
    '',
    'Recompute with `src/check_mg12h3_tick_accuracy.py`, `src/recompute_mg158_accuracy.py`, and `src/report_mg158.py`. Do not rerun production to replace samples. Specification: `spec/MG12H3_tick_accuracy_draft.md`.','']
    (BASE/'MG12H3_tick_accuracy_results.md').write_text('\n'.join(lines),encoding='utf-8');print(json.dumps(dict(outcome='EQUIVALENT both candidate ticks',worst_interval_edge_fractions=edges,worker_seconds=charged,wall_hours=wall/3600)))
if __name__=='__main__':report()
